-- 부정 질문(않은·아닌·없는)에 밑줄 표시
update public.lessons set content = $json${"intro": "냉장고 문에 붙은 자석, 필통 뚜껑의 자석! 자석은 왜 어떤 것은 붙고 어떤 것은 안 붙을까요?", "sections": [{"heading": "자석에 붙는 물체, 붙지 않는 물체", "paras": ["자석은 철로 된 물체를 끌어당겨요. 클립, 철 못, 철 숟가락처럼 철로 만든 물체는 자석에 붙어요.", "나무, 플라스틱, 유리, 종이, 고무로 만든 물체는 자석에 붙지 않아요. 알루미늄 캔이나 동전처럼 '금속'이어도 철이 아니면 붙지 않아요."], "example": "철 캔은 자석에 붙지만 알루미늄 캔은 붙지 않아서, 재활용 공장에서는 자석으로 두 캔을 골라내요.", "figure": "자석에 붙는 물체(클립, 철 못)와 붙지 않는 물체(지우개, 연필, 알루미늄 캔)를 나누어 놓은 그림"}, {"heading": "자석의 극", "paras": ["자석에서 철로 된 물체가 가장 많이 붙는 부분을 '자석의 극'이라고 해요. 막대자석은 양쪽 끝이 극이에요.", "자석에는 N극과 S극, 두 개의 극이 있어요. 자석을 아무리 잘라도 조각마다 다시 N극과 S극이 생겨요."], "example": "막대자석을 클립 상자에 넣었다 빼면 양쪽 끝에 클립이 가장 많이 붙어 나와요.", "figure": "막대자석의 양쪽 끝에 클립이 잔뜩 붙고 가운데는 거의 붙지 않은 모습"}, {"heading": "밀고 당기는 자석", "paras": ["두 자석을 가까이 가져가면, 같은 극끼리는 서로 밀어 내고 다른 극끼리는 서로 끌어당겨요.", "즉 N극과 N극, S극과 S극은 밀어 내고 N극과 S극은 끌어당겨요."], "example": "자석 장난감 기차는 다른 극끼리 마주 보게 해야 착 붙어요.", "figure": "N극-S극은 당기는 화살표, N극-N극은 밀어 내는 화살표로 표시한 두 막대자석 그림"}, {"heading": "자석은 방향을 알려 줘요", "paras": ["막대자석을 물에 띄운 접시에 올려놓으면 빙글 돌다가 N극은 북쪽, S극은 남쪽을 가리키며 멈춰요.", "이 성질을 이용한 것이 '나침반'이에요. 나침반 바늘도 자석이라서 늘 북쪽과 남쪽을 가리키지요. 그래서 나침반 가까이에 자석을 대면 바늘이 엉뚱한 쪽으로 움직여요."], "example": "길을 잃었을 때 나침반으로 북쪽을 찾을 수 있어요.", "figure": "나침반 바늘의 N극이 북쪽을 가리키는 모습"}, {"heading": "생활 속 자석", "paras": ["자석은 우리 생활 곳곳에서 쓰여요. 냉장고 문, 자석 칠판, 가방 여밈 장치, 자석 다트 등이 있어요.", "자석은 철로 된 물체를 사이에 다른 물체가 있어도 끌어당길 수 있어요. 그래서 종이를 사이에 두고도 자석으로 칠판에 붙일 수 있어요."], "example": "", "figure": "냉장고 문, 자석 칠판, 가방 자석 단추 등 생활 속 자석 사진 모음"}], "keywords": [{"word": "자석", "meaning": "철로 된 물체를 끌어당기는 물체"}, {"word": "자석의 극", "meaning": "자석에서 철을 가장 세게 끌어당기는 부분"}, {"word": "N극", "meaning": "자유롭게 움직이게 두면 북쪽을 가리키는 자석의 극"}, {"word": "S극", "meaning": "자유롭게 움직이게 두면 남쪽을 가리키는 자석의 극"}, {"word": "나침반", "meaning": "자석 바늘로 방향을 알려 주는 도구"}], "expressions": [], "quiz": [{"q": "다음 중 자석에 붙는 물체는?", "choices": ["플라스틱 자", "철 클립", "나무젓가락", "고무지우개"], "answer": 1, "explain": "자석은 철로 된 물체를 끌어당겨요."}, {"q": "막대자석에서 클립이 가장 많이 붙는 곳은?", "choices": ["가운데", "양쪽 끝", "모든 곳에 똑같이", "아무 곳에도 안 붙는다"], "answer": 1, "explain": "자석의 극은 막대자석의 양쪽 끝에 있어서 클립이 가장 많이 붙어요."}, {"q": "두 자석의 N극과 N극을 가까이 하면 어떻게 될까요?", "choices": ["끌어당긴다", "아무 일도 없다", "서로 밀어 낸다", "색이 변한다"], "answer": 2, "explain": "같은 극끼리는 서로 밀어 내요."}, {"q": "물에 띄운 막대자석의 N극은 어느 쪽을 가리키며 멈출까요?", "choices": ["북쪽", "남쪽", "동쪽", "서쪽"], "answer": 0, "explain": "자석의 N극은 북쪽, S극은 남쪽을 가리켜요."}, {"q": "다음 중 자석에 붙지 __않는__ 금속은?", "choices": ["철 못", "철 숟가락", "철 캔", "알루미늄 캔"], "answer": 3, "explain": "금속이라도 철이 아니면 자석에 붙지 않아요."}], "summary": ["자석은 철로 된 물체를 끌어당겨요.", "자석에는 N극과 S극이 있고, 같은 극은 밀고 다른 극은 당겨요.", "자석의 N극은 북쪽을 가리키며, 이를 이용한 것이 나침반이에요."], "parent_tip": "부모님께: 아이들은 '금속은 모두 자석에 붙는다'고 생각하기 쉽습니다. 집에 있는 동전, 알루미늄 포일, 철 숟가락, 스테인리스 그릇 등을 자석에 대 보며 '왜 이건 안 붙을까?'를 함께 이야기해 보세요(스테인리스는 종류에 따라 붙기도 하고 안 붙기도 합니다)."}$json$::jsonb where slug = 's3-02';
update public.lessons set content = $json${"intro": "햇빛 좋은 날 운동장에 서면 내 발밑에 까만 그림자가 따라다녀요. 그림자는 어떻게 생기는 걸까요?", "sections": [{"heading": "빛은 곧게 나아가요", "paras": ["손전등을 켜면 빛이 똑바로 뻗어 나가요. 이렇게 빛이 곧게 나아가는 성질을 '빛의 직진'이라고 해요.", "빛이 곧게 나아가다가 물체에 막히면, 물체 뒤쪽으로는 빛이 가지 못해요."], "example": "구름 사이로 햇빛이 쭉쭉 곧은 줄처럼 내려오는 모습을 볼 수 있어요.", "figure": "어두운 방에서 손전등 빛이 곧은 줄기로 뻗어 나가는 모습"}, {"heading": "그림자가 생기는 까닭", "paras": ["그림자가 생기려면 빛, 물체, 그리고 그림자가 비칠 스크린(벽, 땅 등)이 필요해요.", "빛이 곧게 나아가다 물체에 막히면 물체 뒤쪽 스크린에 빛이 닿지 않아 어두운 그림자가 생겨요. 그래서 그림자 모양은 물체 모양과 비슷해요."], "example": "손으로 강아지 모양을 만들어 벽에 비추면 강아지 그림자가 생겨요.", "figure": "손전등-손-벽 순서로 놓고 벽에 손 그림자가 생긴 그림"}, {"heading": "투명한 물체와 불투명한 물체", "paras": ["유리컵처럼 빛이 대부분 통과하는 물체는 연한 그림자가 생겨요. 도자기 컵처럼 빛이 통과하지 못하는 물체는 진한 그림자가 생겨요.", "그림자의 진하기는 물체가 빛을 얼마나 통과시키는지에 따라 달라져요."], "example": "투명한 비닐우산 아래는 밝고, 검은 우산 아래는 어두워요.", "figure": "유리컵의 연한 그림자와 도자기 컵의 진한 그림자를 나란히 비교한 그림"}, {"heading": "그림자의 크기 바꾸기", "paras": ["손전등과 스크린은 그대로 두고 물체를 손전등에 가까이 가져가면 그림자가 커지고, 멀리 하면 그림자가 작아져요.", "또 같은 물체라도 놓는 방향을 바꾸면 그림자 모양이 달라질 수 있어요. 원기둥은 세우면 네모, 눕혀서 밑면을 비추면 동그라미 그림자가 생겨요."], "example": "인형극에서 인형을 불빛 가까이 대면 무대에 거인처럼 큰 그림자가 생겨요.", "figure": "물체가 손전등에 가까울 때 큰 그림자, 멀 때 작은 그림자가 생기는 두 장면 비교"}, {"heading": "거울은 빛을 되돌려요", "paras": ["빛이 나아가다 거울에 부딪치면 방향이 바뀌어 되돌아 나와요. 이것을 '빛의 반사'라고 해요.", "거울에 비친 모습은 실제와 좌우가 바뀌어 보여요. 오른손을 들면 거울 속 나는 왼손을 든 것처럼 보이지요."], "example": "구급차 앞에 글자를 좌우로 바꿔 써 두면, 앞차 운전자가 뒤를 보는 거울로 볼 때 바르게 읽혀요.", "figure": "거울에 부딪친 빛의 방향이 꺾여 나가는 화살표 그림"}], "keywords": [{"word": "빛의 직진", "meaning": "빛이 곧게 나아가는 성질"}, {"word": "그림자", "meaning": "빛이 물체에 막혀 물체 뒤에 생기는 어두운 부분"}, {"word": "투명한 물체", "meaning": "빛이 대부분 통과하는 물체"}, {"word": "불투명한 물체", "meaning": "빛이 통과하지 못하는 물체"}, {"word": "빛의 반사", "meaning": "빛이 거울 같은 물체에 부딪쳐 방향이 바뀌어 나아가는 것"}], "expressions": [], "quiz": [{"q": "그림자가 생기는 까닭과 가장 관계있는 빛의 성질은?", "choices": ["빛이 곧게 나아간다", "빛은 따뜻하다", "빛은 여러 색이다", "빛은 소리를 낸다"], "answer": 0, "explain": "빛이 곧게 나아가다 물체에 막혀 뒤쪽에 그림자가 생겨요."}, {"q": "진한 그림자가 생기는 물체는?", "choices": ["유리컵", "투명 비닐", "도자기 컵", "투명 플라스틱 판"], "answer": 2, "explain": "빛이 통과하지 못하는 불투명한 물체는 진한 그림자가 생겨요."}, {"q": "손전등과 스크린은 그대로 두고 물체를 손전등에 가까이 하면 그림자는?", "choices": ["작아진다", "커진다", "사라진다", "색이 변한다"], "answer": 1, "explain": "물체가 손전등에 가까울수록 빛을 더 많이 가려 그림자가 커져요."}, {"q": "거울 앞에서 오른손을 들면 거울 속 나는 어느 손을 든 것처럼 보일까요?", "choices": ["오른손", "양손", "손을 안 든다", "왼손"], "answer": 3, "explain": "거울에 비친 모습은 좌우가 바뀌어 보여요."}, {"q": "그림자가 생기는 데 꼭 필요하지 __않은__ 것은?", "choices": ["빛", "물체", "스크린", "소리"], "answer": 3, "explain": "그림자는 빛, 물체, 스크린이 있으면 생겨요."}], "summary": ["빛은 곧게 나아가고, 물체에 막히면 그림자가 생겨요.", "불투명한 물체는 진한 그림자, 투명한 물체는 연한 그림자가 생겨요.", "물체가 빛에 가까울수록 그림자가 커지고, 거울은 빛을 반사해요."], "parent_tip": "부모님께: 아이들은 그림자가 물체에 '붙어 있는' 것이라 생각하기도 합니다. 밤에 손전등과 인형으로 그림자 놀이를 하며 '그림자를 크게 만들려면 어떻게 할까?', '그림자 모양을 동그라미로 바꿀 수 있을까?'를 물어보면 좋습니다."}$json$::jsonb where slug = 's3-03';
update public.lessons set content = $json${"intro": "콩, 팥, 좁쌀이 한 그릇에 뒤섞였어요. 하나하나 손으로 골라내려면 너무 오래 걸리겠죠? 더 쉬운 방법이 있을까요?", "sections": [{"heading": "혼합물이란?", "paras": ["두 가지 이상의 물질이 섞여 있는 것을 '혼합물'이라고 해요. 섞여 있어도 각 물질의 성질은 그대로 남아 있어요.", "김밥, 팥빙수, 잡곡, 바닷물(물+소금)도 모두 혼합물이에요. 그래서 각 물질의 성질 차이를 이용하면 다시 나눌(분리할) 수 있어요."], "example": "콩·팥·좁쌀을 섞어도 콩은 콩대로, 팥은 팥대로 크기와 색이 그대로예요.", "figure": "콩, 팥, 좁쌀이 섞인 그릇 그림"}, {"heading": "알갱이 크기로 나누기 – 체", "paras": ["알갱이의 크기가 다른 혼합물은 '체'로 나눌 수 있어요. 체의 눈보다 작은 알갱이는 빠져나가고 큰 알갱이는 체에 남아요.", "눈의 크기가 다른 체를 차례로 쓰면 콩, 팥, 좁쌀을 모두 나눌 수 있어요."], "example": "모래사장에서 체로 모래를 거르면 조개껍데기만 남아요.", "figure": "눈 크기가 다른 체 두 개로 콩, 팥, 좁쌀을 차례로 분리하는 과정 그림"}, {"heading": "자석으로 나누기", "paras": ["철로 된 물체가 섞여 있으면 자석으로 쉽게 골라낼 수 있어요. 자석에 붙는 성질을 이용한 것이지요.", "재활용 공장에서는 큰 자석으로 철 캔과 알루미늄 캔을 나눠요."], "example": "모래 속에 섞인 철 가루는 자석을 대면 자석에 달라붙어 나와요.", "figure": "모래와 철 가루 혼합물에 자석을 대어 철 가루만 끌려 나오는 모습"}, {"heading": "물에 녹는 성질로 나누기 – 거름", "paras": ["소금과 모래가 섞여 있으면 먼저 물을 부어 저어요. 소금은 물에 녹고 모래는 녹지 않아요.", "이것을 거름종이를 올린 깔때기에 부으면 모래는 거름종이 위에 남고 소금물만 아래로 빠져요. 이렇게 거름종이로 거르는 것을 '거름'이라고 해요."], "example": "커피를 내릴 때 커피 가루는 필터에 남고 커피 물만 내려오는 것도 거름이에요.", "figure": "깔때기에 거름종이를 끼우고 소금물과 모래를 부어 거르는 실험 장치 그림"}, {"heading": "물을 날려 보내 나누기 – 증발", "paras": ["거름으로 얻은 소금물을 가열하거나 햇볕에 오래 두면 물이 증발해 날아가고 하얀 소금만 남아요.", "바닷가 염전에서는 바닷물을 햇볕과 바람에 증발시켜 소금을 얻어요."], "example": "", "figure": "넓은 염전에 바닷물을 가두고 하얀 소금을 긁어모으는 모습"}], "keywords": [{"word": "혼합물", "meaning": "두 가지 이상의 물질이 섞여 있는 것"}, {"word": "분리", "meaning": "섞여 있는 물질을 나누는 것"}, {"word": "체", "meaning": "알갱이 크기 차이로 물질을 나누는 도구"}, {"word": "거름", "meaning": "거름종이로 녹지 않은 물질을 걸러 내는 방법"}, {"word": "증발", "meaning": "물이 표면에서 수증기가 되어 날아가는 것"}], "expressions": [], "quiz": [{"q": "다음 중 혼합물이 __아닌__ 것은?", "choices": ["팥빙수", "잡곡", "바닷물", "순수한 물"], "answer": 3, "explain": "순수한 물은 한 가지 물질이에요. 나머지는 여러 물질이 섞인 혼합물이에요."}, {"q": "콩과 좁쌀이 섞여 있을 때 가장 쉽게 나누는 방법은?", "choices": ["체로 거른다", "물에 녹인다", "불로 태운다", "자석을 댄다"], "answer": 0, "explain": "콩과 좁쌀은 알갱이 크기가 달라서 체로 나눌 수 있어요."}, {"q": "모래와 철 가루를 나누는 데 알맞은 도구는?", "choices": ["거름종이", "체", "자석", "돋보기"], "answer": 2, "explain": "철 가루는 자석에 붙고 모래는 붙지 않아요."}, {"q": "소금과 모래 혼합물을 물에 녹여 거르면 거름종이 위에 남는 것은?", "choices": ["소금", "모래", "소금물", "아무것도 안 남는다"], "answer": 1, "explain": "모래는 물에 녹지 않아 거름종이 위에 남고, 소금은 물에 녹아 빠져나가요."}, {"q": "소금물에서 소금을 얻으려면 어떻게 해야 할까요?", "choices": ["체로 거른다", "자석을 댄다", "얼린다", "물을 증발시킨다"], "answer": 3, "explain": "물이 증발해 날아가면 소금만 남아요."}], "summary": ["혼합물은 여러 물질이 섞인 것이고, 섞여도 각 물질의 성질은 그대로예요.", "크기는 체, 철은 자석, 녹는 성질은 거름으로 나눠요.", "소금물의 물을 증발시키면 소금을 얻을 수 있어요."], "parent_tip": "부모님께: 아이들은 소금이 물에 녹으면 '없어졌다'고 생각하곤 합니다. 소금물을 조금 맛보게 하거나 접시에 담아 며칠 두어 소금이 다시 나타나는 것을 보여 주세요. '주방에서 혼합물을 나누는 도구는 뭐가 있을까?'(체, 커피 필터, 국자 등)를 함께 찾아보는 것도 좋습니다."}$json$::jsonb where slug = 's3-05';
update public.lessons set content = $json${"intro": "밤하늘의 둥근 달을 보면 토끼 모양 무늬가 보여요. 달은 어떤 곳일까요? 그리고 우리가 사는 지구는 어떤 모습일까요?", "sections": [{"heading": "지구는 둥글어요", "paras": ["우주에서 찍은 사진을 보면 지구는 공처럼 둥근 모양이에요. 지구가 너무 커서 땅 위에 서 있는 우리에게는 평평해 보일 뿐이에요.", "지구 표면에는 육지와 바다가 있는데, 바다가 육지보다 훨씬 넓어요. 바다가 지구 표면의 약 70%를 차지해요."], "example": "멀리서 다가오는 배는 꼭대기의 돛부터 보이기 시작하는데, 지구가 둥글기 때문이에요.", "figure": "우주에서 본 파랗고 둥근 지구 사진"}, {"heading": "지구에는 공기와 물이 있어요", "paras": ["지구는 공기로 둘러싸여 있어요. 공기가 있어서 생물이 숨을 쉴 수 있고, 바람이 불고 구름이 생겨요.", "또 지구에는 물이 있어 생물이 살아갈 수 있어요. 알맞은 온도, 공기, 물이 있어서 지구에는 많은 생물이 살아요."], "example": "", "figure": "공기층에 둘러싸인 지구와 바다, 숲, 동물을 함께 그린 그림"}, {"heading": "달은 어떻게 생겼을까요?", "paras": ["달도 지구처럼 둥근 공 모양이에요. 크기는 지구보다 작아서 지름이 지구의 약 4분의 1이에요.", "달 표면의 어둡게 보이는 넓은 곳을 '달의 바다'라고 하는데, 실제로 물이 있는 것은 아니에요. 또 달 표면에는 운석이 부딪쳐 생긴 움푹 파인 구덩이인 '충돌 구덩이(크레이터)'가 많아요."], "example": "보름달의 어두운 무늬(달의 바다)를 보고 옛사람들은 방아 찧는 토끼를 떠올렸어요.", "figure": "달 표면의 어두운 '바다'와 둥근 충돌 구덩이를 표시한 사진"}, {"heading": "지구와 달 비교하기", "paras": ["달에는 공기와 물이 없어요. 그래서 바람이 불지 않고, 생물이 살 수 없어요. 공기가 없어서 소리도 전해지지 않아요.", "또 낮에는 아주 뜨겁고 밤에는 아주 차가워요. 지구는 공기와 물이 있어 생물이 살기에 알맞은 환경이에요."], "example": "달에 간 우주 비행사의 발자국은 바람이 없어서 오랫동안 그대로 남아 있어요.", "figure": "지구와 달을 나란히 놓고 공기·물·생물 유무를 표로 비교한 그림"}], "keywords": [{"word": "육지", "meaning": "지구 표면에서 물로 덮이지 않은 땅"}, {"word": "바다", "meaning": "지구 표면에서 짠물로 덮인 넓은 곳"}, {"word": "공기", "meaning": "지구를 둘러싸고 있어 생물이 숨 쉴 수 있게 해 주는 기체"}, {"word": "달의 바다", "meaning": "달 표면에서 어둡게 보이는 넓고 평평한 곳(물은 없음)"}, {"word": "충돌 구덩이", "meaning": "운석이 부딪쳐 생긴 둥글게 움푹 파인 곳"}], "expressions": [], "quiz": [{"q": "지구 표면에서 더 넓은 곳은?", "choices": ["육지", "바다", "둘이 같다", "알 수 없다"], "answer": 1, "explain": "바다가 지구 표면의 약 70%를 차지해 육지보다 넓어요."}, {"q": "달에 대한 설명으로 옳은 것은?", "choices": ["공기가 많다", "바다에 물이 가득하다", "공기와 물이 없다", "생물이 많이 산다"], "answer": 2, "explain": "달에는 공기와 물이 없어서 생물이 살 수 없어요."}, {"q": "달 표면에 있는 둥글게 움푹 파인 곳을 무엇이라고 할까요?", "choices": ["충돌 구덩이", "화산", "강", "바다"], "answer": 0, "explain": "운석이 부딪쳐 생긴 구덩이를 충돌 구덩이(크레이터)라고 해요."}, {"q": "지구에 생물이 살 수 있는 까닭으로 알맞지 __않은__ 것은?", "choices": ["물이 있다", "공기가 있다", "알맞은 온도이다", "충돌 구덩이가 많다"], "answer": 3, "explain": "지구에는 물, 공기, 알맞은 온도가 있어 생물이 살 수 있어요."}, {"q": "달에서 우주 비행사의 발자국이 오래 남는 까닭은?", "choices": ["달이 차가워서", "달이 작아서", "바람이 불지 않아서", "달이 둥글어서"], "answer": 2, "explain": "달에는 공기가 없어 바람이 불지 않아 발자국이 지워지지 않아요."}], "summary": ["지구는 둥글고, 바다가 육지보다 넓어요.", "지구에는 공기와 물이 있어 생물이 살 수 있어요.", "달은 둥글고 지구보다 작으며, 공기와 물이 없고 충돌 구덩이가 많아요."], "parent_tip": "부모님께: '달의 바다'라는 이름 때문에 달에 물이 있다고 오해하는 아이가 많습니다. 보름달이 뜨는 날 함께 달을 보며 어두운 무늬를 찾아보고, '달에 가면 친구 목소리가 들릴까?'처럼 지구와 비교하는 질문을 해 보세요."}$json$::jsonb where slug = 's3-09';
update public.lessons set content = $json${"intro": "돋보기로 개미를 보면 커다랗게 보이고, 햇빛을 한 점에 모으면 종이를 태울 수도 있어요. 렌즈는 어떻게 빛을 다룰까요?", "sections": [{"heading": "햇빛은 여러 빛깔로 되어 있어요", "paras": ["햇빛을 프리즘에 통과시키면 하얀 종이 위에 빨강, 주황, 노랑, 초록, 파랑, 남색, 보라처럼 여러 빛깔이 나타나요.", "이것으로 햇빛이 여러 가지 빛깔의 빛으로 이루어져 있다는 것을 알 수 있어요."], "example": "비가 그친 뒤 하늘에 생기는 무지개는 공기 중 물방울이 프리즘처럼 햇빛을 여러 빛깔로 나눈 거예요.", "figure": "프리즘을 통과한 햇빛이 무지갯빛으로 나뉘는 그림"}, {"heading": "빛은 경계에서 꺾여요 – 굴절", "paras": ["빛이 공기 중에서 물이나 유리로 비스듬히 들어가면 두 물질의 경계에서 꺾여 나아가요. 이것을 '빛의 굴절'이라고 해요.", "빛이 경계에 수직으로(똑바로) 들어가면 꺾이지 않고 그대로 나아가요."], "example": "물이 든 컵에 젓가락을 넣으면 젓가락이 수면에서 꺾여 보여요.", "figure": "물컵 속 젓가락이 수면에서 꺾여 보이는 모습과 빛이 꺾이는 경로 화살표"}, {"heading": "볼록 렌즈의 특징", "paras": ["볼록 렌즈는 가운데가 가장자리보다 두꺼운 렌즈예요. 볼록 렌즈를 통과한 빛은 굴절하여 한 곳으로 모여요.", "햇빛을 볼록 렌즈로 모으면 빛이 모인 곳은 더 밝고 온도도 높아요. 그래서 검은 종이를 태울 수 있어요(눈으로 직접 보면 위험해요!)."], "example": "물이 담긴 둥근 어항이나 유리구슬도 볼록 렌즈처럼 빛을 모을 수 있어요.", "figure": "볼록 렌즈를 통과한 평행한 햇빛이 한 점으로 모이는 그림"}, {"heading": "볼록 렌즈로 본 모습", "paras": ["볼록 렌즈로 가까운 물체를 보면 실제보다 크게 보여요. 멀리 있는 물체를 보면 상하좌우가 바뀌어(거꾸로) 보이기도 해요.", "볼록 렌즈의 성질을 이용한 도구로는 돋보기, 현미경, 망원경, 사진기, 확대경 등이 있어요."], "example": "간이 사진기를 만들면 볼록 렌즈 때문에 스크린에 바깥 풍경이 거꾸로 비쳐요.", "figure": "돋보기로 가까운 글자는 크게, 먼 풍경은 거꾸로 보이는 두 장면 비교"}], "keywords": [{"word": "프리즘", "meaning": "빛을 여러 빛깔로 나누는 투명한 삼각기둥 모양의 기구"}, {"word": "빛의 굴절", "meaning": "빛이 서로 다른 물질의 경계에서 꺾여 나아가는 것"}, {"word": "볼록 렌즈", "meaning": "가운데가 가장자리보다 두꺼운 렌즈"}, {"word": "돋보기", "meaning": "볼록 렌즈로 물체를 크게 보이게 하는 도구"}, {"word": "간이 사진기", "meaning": "볼록 렌즈와 스크린으로 만든 간단한 사진기"}], "expressions": [], "quiz": [{"q": "프리즘에 햇빛을 통과시키면 어떻게 될까요?", "choices": ["빛이 사라진다", "여러 빛깔로 나뉜다", "검은색이 된다", "빛이 더 하얘진다"], "answer": 1, "explain": "햇빛은 여러 빛깔의 빛으로 이루어져 있어 프리즘을 지나면 나뉘어 보여요."}, {"q": "물이 든 컵 속 젓가락이 꺾여 보이는 까닭은?", "choices": ["빛의 굴절", "빛의 반사", "그림자", "소리의 반사"], "answer": 0, "explain": "빛이 물과 공기의 경계에서 꺾이기 때문이에요."}, {"q": "볼록 렌즈의 모양으로 옳은 것은?", "choices": ["가장자리가 가운데보다 두껍다", "모든 곳의 두께가 같다", "가운데가 가장자리보다 두껍다", "가운데에 구멍이 있다"], "answer": 2, "explain": "볼록 렌즈는 가운데가 가장자리보다 두꺼워요."}, {"q": "볼록 렌즈를 이용한 도구가 __아닌__ 것은?", "choices": ["돋보기", "현미경", "사진기", "평면 거울"], "answer": 3, "explain": "평면 거울은 빛을 반사하는 도구이고 렌즈가 아니에요."}, {"q": "볼록 렌즈로 햇빛을 모은 곳의 특징은?", "choices": ["더 어둡고 차갑다", "더 밝고 온도가 높다", "색이 검게 변한다", "아무 변화가 없다"], "answer": 1, "explain": "빛이 한 곳에 모여서 그곳은 밝고 뜨거워져요."}], "summary": ["햇빛은 여러 빛깔의 빛으로 이루어져 있어요.", "빛은 서로 다른 물질의 경계에서 꺾여요(굴절).", "볼록 렌즈는 빛을 모으고, 물체를 크게 또는 거꾸로 보이게 해요."], "parent_tip": "부모님께: 아이들은 빛의 '반사'와 '굴절'을 헷갈려 합니다. 거울에 비친 모습은 반사, 물컵 속 빨대가 꺾여 보이는 것은 굴절이라고 짝지어 주세요. 돋보기로 햇빛을 모으는 활동은 반드시 보호자와 함께하고, 렌즈로 해를 직접 보지 않도록 알려 주세요."}$json$::jsonb where slug = 's5-03';
update public.lessons set content = $json${"intro": "밤하늘에는 반짝이는 별이 가득해요. 그런데 그중에는 별이 아닌 '행성'도 섞여 있다는 사실, 알고 있나요?", "sections": [{"heading": "태양은 우리에게 꼭 필요해요", "paras": ["태양은 스스로 빛과 열을 내는 별이에요. 태양 빛 덕분에 식물이 양분을 만들고, 동물은 그 식물을 먹고 살아요.", "태양은 물을 증발시켜 비와 눈이 내리게 하고, 우리가 생활하기에 알맞은 온도를 만들어 줘요. 태양이 없다면 지구의 생물은 살 수 없어요."], "example": "햇빛으로 전기를 만드는 태양 전지판, 바닷물을 말려 소금을 얻는 염전도 태양 에너지를 이용해요.", "figure": "태양 빛을 받아 자라는 식물, 태양 전지판, 염전 그림"}, {"heading": "태양계의 구성원", "paras": ["태양과 태양의 영향을 받는 천체들, 그리고 그 공간을 '태양계'라고 해요. 태양계의 중심에는 태양이 있어요.", "태양 둘레를 도는 행성은 태양에서 가까운 순서대로 수성, 금성, 지구, 화성, 목성, 토성, 천왕성, 해왕성 8개예요. 달처럼 행성 둘레를 도는 천체는 '위성'이라고 해요."], "example": "외우기 팁: '수·금·지·화·목·토·천·해'!", "figure": "태양을 중심으로 8개 행성이 순서대로 늘어선 태양계 그림"}, {"heading": "행성의 크기와 거리", "paras": ["태양계 행성 중 가장 큰 것은 목성이고, 가장 작은 것은 수성이에요. 지구를 기준으로 보면 목성은 지름이 지구의 약 11배나 돼요.", "수성, 금성, 지구, 화성은 상대적으로 작고 표면이 암석으로 되어 있어요. 목성, 토성, 천왕성, 해왕성은 크고 주로 기체로 되어 있으며 고리가 있어요. 태양에서 멀수록 행성 사이의 거리도 대체로 멀어요."], "example": "지구 지름을 1이라고 하면 목성은 약 11.2, 수성은 약 0.4예요.", "figure": "지구 크기를 1로 놓고 8개 행성의 크기를 비교한 막대 또는 원 그림"}, {"heading": "별과 행성은 달라요", "paras": ["별은 태양처럼 스스로 빛을 내는 천체예요. 행성은 스스로 빛을 내지 못하고 태양 빛을 반사해서 밝게 보여요.", "별은 아주 멀리 있어서 여러 날 관측해도 위치가 거의 변하지 않지만, 행성은 태양 둘레를 돌기 때문에 여러 날 관측하면 별들 사이에서 위치가 조금씩 바뀌어요."], "example": "새벽이나 저녁에 아주 밝게 보이는 '샛별'은 별이 아니라 행성인 금성이에요.", "figure": "며칠 동안 별자리 사이에서 위치가 바뀐 행성을 점선으로 표시한 그림"}, {"heading": "북쪽 하늘의 별자리와 북극성", "paras": ["옛날 사람들은 밝은 별들을 이어 동물이나 물건 모양을 떠올려 '별자리'라고 이름 붙였어요. 북쪽 하늘에는 북두칠성, 카시오페이아자리, 작은곰자리가 있어요.", "북극성은 항상 북쪽 하늘에 있어서 방위를 찾는 데 도움이 돼요. 북두칠성 국자 끝의 두 별을 이은 거리의 약 5배만큼 떨어진 곳에 북극성이 있어요. 카시오페이아자리를 이용해서도 찾을 수 있어요."], "example": "북극성을 바라보면 내가 바라보는 쪽이 북쪽, 등 뒤가 남쪽이에요.", "figure": "북두칠성 국자 끝 두 별에서 5배 거리에 북극성을 찾는 방법을 나타낸 별자리 그림"}], "keywords": [{"word": "태양계", "meaning": "태양과 태양의 영향을 받는 천체들, 그리고 그 공간"}, {"word": "행성", "meaning": "태양 둘레를 도는, 스스로 빛을 내지 못하는 천체"}, {"word": "위성", "meaning": "행성 둘레를 도는 천체(예: 달)"}, {"word": "별", "meaning": "스스로 빛을 내는 천체"}, {"word": "별자리", "meaning": "밝은 별들을 이어 이름을 붙인 것"}, {"word": "북극성", "meaning": "항상 북쪽 하늘에 있어 방위를 알려 주는 별"}], "expressions": [], "quiz": [{"q": "태양계에서 가장 큰 행성은?", "choices": ["지구", "토성", "목성", "해왕성"], "answer": 2, "explain": "목성이 가장 크며 지름이 지구의 약 11배예요."}, {"q": "태양에서 가장 가까운 행성은?", "choices": ["수성", "금성", "지구", "화성"], "answer": 0, "explain": "태양에서 가까운 순서는 수성, 금성, 지구, 화성…이에요."}, {"q": "별과 행성의 차이로 옳은 것은?", "choices": ["행성은 스스로 빛을 낸다", "별은 태양 둘레를 돈다", "별은 스스로 빛을 내고, 행성은 태양 빛을 반사한다", "별과 행성은 같은 것이다"], "answer": 2, "explain": "별은 스스로 빛을 내지만 행성은 태양 빛을 반사해 밝게 보여요."}, {"q": "북두칠성으로 북극성을 찾을 때, 국자 끝 두 별 사이 거리의 몇 배만큼 가면 될까요?", "choices": ["2배", "3배", "5배", "10배"], "answer": 2, "explain": "국자 끝 두 별을 이은 거리의 약 5배 떨어진 곳에 북극성이 있어요."}, {"q": "태양이 우리 생활에 주는 영향이 __아닌__ 것은?", "choices": ["식물이 양분을 만든다", "물이 증발해 비가 내린다", "알맞은 온도를 만든다", "밀물과 썰물을 주로 일으킨다"], "answer": 3, "explain": "밀물과 썰물은 주로 달의 영향으로 생겨요. 나머지는 태양 덕분이에요."}], "summary": ["태양은 스스로 빛과 열을 내며 지구의 생물에게 꼭 필요해요.", "태양계 행성은 수성·금성·지구·화성·목성·토성·천왕성·해왕성 8개이고, 목성이 가장 커요.", "별은 스스로 빛을 내고, 북극성은 북두칠성이나 카시오페이아자리로 찾을 수 있어요."], "parent_tip": "부모님께: 아이들은 '밤하늘에서 반짝이는 것은 모두 별'이라고 생각하거나 달도 별이라고 말하곤 합니다. 맑은 밤에 함께 북쪽 하늘을 보며 북두칠성을 찾고 북극성까지 따라가 보세요. '샛별은 왜 별이 아닐까?'라는 질문도 좋은 대화 소재입니다."}$json$::jsonb where slug = 's5-04';
update public.lessons set content = $json${"intro": "스위치를 누르면 방에 불이 켜지고, 리모컨으로 텔레비전이 켜져요. 전기는 어떻게 흘러서 일을 할까요?", "sections": [{"heading": "전기 회로 만들기", "paras": ["전지, 전선, 전구, 스위치 같은 전기 부품을 연결해 전기가 흐르도록 한 것을 '전기 회로'라고 해요.", "전구에 불이 켜지려면 전구를 전지의 (+)극과 (-)극에 각각 연결해, 끊어진 곳 없이 하나의 길로 이어져야 해요. 스위치를 끄면 회로가 끊겨 불이 꺼져요."], "example": "전선 한쪽이 전지에서 빠지면 회로가 끊어져 전구에 불이 켜지지 않아요.", "figure": "전지-스위치-전구가 전선으로 고리처럼 이어진 전기 회로 그림"}, {"heading": "전구의 직렬연결과 병렬연결", "paras": ["전구 두 개 이상을 한 줄로 연결하는 것을 '직렬연결', 여러 갈래로 나누어 연결하는 것을 '병렬연결'이라고 해요.", "전구를 병렬연결하면 직렬연결할 때보다 전구가 더 밝아요. 또 병렬연결에서는 전구 하나가 꺼져도 나머지 전구는 계속 켜져 있지만, 직렬연결에서는 하나가 꺼지면 나머지도 모두 꺼져요."], "example": "집 안의 전등과 전기 기구는 병렬연결되어 있어서 하나를 꺼도 다른 것은 켜져 있어요.", "figure": "전구 두 개를 한 줄로 이은 직렬연결과 두 갈래로 이은 병렬연결을 비교한 회로도"}, {"heading": "전자석", "paras": ["철심(쇠못)에 에나멜선을 여러 번 감고 전기를 흐르게 하면 철심이 자석이 돼요. 이것을 '전자석'이라고 해요.", "전자석은 전기가 흐를 때만 자석이 되고, 전지를 여러 개 직렬로 연결하면 세기가 더 세져요. 또 전지의 극을 바꾸면 전자석의 N극과 S극도 바뀌어요."], "example": "고철 처리장의 기중기는 전자석으로 고철을 들어 올렸다가 전기를 끊어 내려놓아요.", "figure": "쇠못에 에나멜선을 감고 전지에 연결해 클립을 끌어당기는 전자석 그림"}, {"heading": "전기를 안전하고 아껴 쓰기", "paras": ["젖은 손으로 전기 기구를 만지거나, 콘센트 하나에 플러그를 너무 많이 꽂으면 감전이나 화재가 일어날 수 있어 위험해요. 플러그를 뽑을 때는 전선이 아니라 플러그 머리를 잡아요.", "전기를 만들려면 많은 자원이 들어요. 쓰지 않는 전등은 끄고, 사용하지 않는 기구의 플러그는 뽑고, 냉장고 문은 오래 열어 두지 않아요."], "example": "", "figure": "멀티탭에 플러그가 잔뜩 꽂힌 위험한 모습과 안전하게 사용하는 모습 비교 그림"}], "keywords": [{"word": "전기 회로", "meaning": "전기 부품을 연결해 전기가 흐르도록 한 것"}, {"word": "직렬연결", "meaning": "전구나 전지를 한 줄로 연결하는 것"}, {"word": "병렬연결", "meaning": "전구를 여러 갈래로 나누어 연결하는 것"}, {"word": "전자석", "meaning": "전기가 흐를 때만 자석이 되는 것"}, {"word": "감전", "meaning": "몸에 전기가 흘러 다치는 것"}], "expressions": [], "quiz": [{"q": "전구에 불이 켜지는 조건으로 옳은 것은?", "choices": ["전구를 전지의 (+)극과 (-)극에 끊김 없이 연결한다", "전구를 전지의 (+)극에만 연결한다", "전선을 전구에만 감는다", "스위치를 끈다"], "answer": 0, "explain": "전기 부품이 끊어진 곳 없이 이어져야 전기가 흘러요."}, {"q": "전구 두 개를 병렬연결했을 때의 특징은?", "choices": ["직렬연결보다 어둡다", "전구 하나를 빼도 다른 전구는 켜진다", "전구 하나를 빼면 모두 꺼진다", "전지가 필요 없다"], "answer": 1, "explain": "병렬연결은 길이 여러 갈래라서 하나가 꺼져도 나머지는 켜져요. 밝기도 직렬보다 밝아요."}, {"q": "전자석에 대한 설명으로 옳지 __않은__ 것은?", "choices": ["전기가 흐를 때만 자석이 된다", "전지의 극을 바꾸면 극이 바뀐다", "전지를 직렬로 더 연결하면 세기가 세진다", "전기를 끊어도 항상 자석이다"], "answer": 3, "explain": "전자석은 전기가 흐를 때만 자석의 성질을 가져요."}, {"q": "우리 집 전등과 전기 기구는 주로 어떻게 연결되어 있을까요?", "choices": ["직렬연결", "병렬연결", "연결되어 있지 않다", "전자석으로 연결"], "answer": 1, "explain": "병렬연결이라서 하나를 꺼도 다른 기구는 계속 쓸 수 있어요."}, {"q": "전기를 안전하게 사용하는 방법은?", "choices": ["젖은 손으로 플러그를 뽑는다", "콘센트 하나에 플러그를 많이 꽂는다", "플러그를 뽑을 때 플러그 머리를 잡는다", "전선을 잡아당겨 뽑는다"], "answer": 2, "explain": "전선을 당기면 선이 손상될 수 있어 플러그 머리를 잡고 뽑아야 해요."}], "summary": ["전기 부품이 끊김 없이 이어져야 전기 회로에 전기가 흘러요.", "전구는 병렬연결이 직렬연결보다 밝고, 하나가 꺼져도 나머지가 켜져요.", "전자석은 전기가 흐를 때만 자석이 되며, 전기는 안전하게 아껴 써야 해요."], "parent_tip": "부모님께: 아이들은 '직렬'과 '병렬'이라는 말을 자주 헷갈립니다. '한 줄 기차'는 직렬, '여러 갈래 길'은 병렬로 짝지어 기억하게 해 주세요. '거실 전등을 끄면 왜 냉장고는 계속 켜져 있을까?'라고 물어보면 병렬연결을 생활과 연결할 수 있습니다."}$json$::jsonb where slug = 's5-05';
update public.lessons set content = $json${"intro": "캠핑장의 모닥불, 생일 케이크의 촛불! 물질이 탈 때는 무엇이 필요하고, 불을 끄려면 어떻게 해야 할까요?", "sections": [{"heading": "물질이 탈 때 나타나는 현상", "paras": ["물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상을 '연소'라고 해요.", "초나 알코올이 탈 때는 빛과 열이 나서 주변이 밝고 따뜻해지고, 시간이 지나면 탈 물질의 양이 줄어들어요."], "example": "", "figure": "타고 있는 촛불과 알코올램프의 불꽃 모습"}, {"heading": "연소의 세 가지 조건", "paras": ["물질이 타려면 세 가지가 모두 있어야 해요. 바로 '탈 물질', '산소', 그리고 '발화점 이상의 온도'예요.", "발화점은 물질이 불에 직접 닿지 않아도 스스로 타기 시작하는 가장 낮은 온도예요. 물질마다 발화점이 달라서 같은 온도로 가열해도 먼저 불이 붙는 물질이 있어요."], "example": "크기가 다른 아크릴 통으로 촛불을 덮으면 큰 통 안의 촛불이 더 오래 타요. 산소가 더 많기 때문이에요.", "figure": "탈 물질, 산소, 발화점 이상의 온도를 세 꼭짓점으로 한 삼각형 그림"}, {"heading": "연소 후 생기는 물질", "paras": ["초가 타면 물과 이산화 탄소가 생겨요. 푸른색 염화 코발트 종이가 붉게 변하면 물이 생긴 것이에요.", "초가 탄 뒤 집기병에 석회수를 넣고 흔들면 뿌옇게 흐려지는데, 이것으로 이산화 탄소가 생겼음을 알 수 있어요."], "example": "", "figure": "촛불을 덮은 집기병 안쪽 벽의 푸른색 염화 코발트 종이가 붉게 변한 모습과 뿌옇게 흐려진 석회수"}, {"heading": "불을 끄는 방법 – 소화", "paras": ["불을 끄는 것을 '소화'라고 해요. 연소의 세 가지 조건 중 한 가지 이상을 없애면 불이 꺼져요.", "탈 물질을 없애고(촛불 심지 자르기, 가스 밸브 잠그기), 산소를 막고(모래나 담요 덮기, 소화기 사용), 온도를 발화점 아래로 낮추면(물 뿌리기) 불이 꺼져요."], "example": "알코올램프는 뚜껑을 덮어 산소를 막아서 불을 꺼요.", "figure": "심지 자르기, 뚜껑 덮기, 물 뿌리기로 불을 끄는 세 가지 장면"}, {"heading": "화재 안전", "paras": ["기름이나 전기 때문에 난 불에 물을 뿌리면 불이 더 커지거나 감전될 수 있어서 소화기나 모래를 써야 해요.", "불이 나면 '불이야!' 하고 크게 외치고 119에 신고해요. 젖은 수건으로 코와 입을 막고 몸을 낮춰 계단으로 대피해요. 승강기(엘리베이터)는 타지 않아요."], "example": "", "figure": "젖은 수건으로 입을 막고 몸을 낮춰 비상구로 대피하는 어린이 그림"}], "keywords": [{"word": "연소", "meaning": "물질이 산소와 빠르게 반응하여 빛과 열을 내는 현상"}, {"word": "발화점", "meaning": "물질이 불에 직접 닿지 않아도 스스로 타기 시작하는 온도"}, {"word": "소화", "meaning": "불을 끄는 것"}, {"word": "석회수", "meaning": "이산화 탄소를 만나면 뿌옇게 흐려지는 용액"}, {"word": "염화 코발트 종이", "meaning": "물에 닿으면 푸른색에서 붉은색으로 변하는 종이"}], "expressions": [], "quiz": [{"q": "연소의 조건이 __아닌__ 것은?", "choices": ["탈 물질", "산소", "발화점 이상의 온도", "이산화 탄소"], "answer": 3, "explain": "연소에는 탈 물질, 산소, 발화점 이상의 온도가 필요해요."}, {"q": "초가 탄 뒤 석회수가 뿌옇게 흐려졌다면 어떤 물질이 생긴 것일까요?", "choices": ["물", "산소", "이산화 탄소", "질소"], "answer": 2, "explain": "석회수는 이산화 탄소를 만나면 뿌옇게 흐려져요."}, {"q": "알코올램프 뚜껑을 덮어 불을 끄는 것은 어떤 조건을 없앤 것일까요?", "choices": ["탈 물질", "산소", "발화점 이상의 온도", "빛"], "answer": 1, "explain": "뚜껑을 덮으면 산소가 공급되지 않아 불이 꺼져요."}, {"q": "불이 났을 때 올바른 행동은?", "choices": ["승강기를 타고 빨리 내려간다", "젖은 수건으로 코와 입을 막고 몸을 낮춰 대피한다", "기름에 붙은 불에 물을 붓는다", "숨어서 기다린다"], "answer": 1, "explain": "연기를 마시지 않도록 코와 입을 막고 몸을 낮춰 계단으로 대피해요."}, {"q": "크기가 다른 통으로 같은 촛불을 덮었을 때 더 오래 타는 경우는?", "choices": ["작은 통", "큰 통", "둘이 같다", "통을 덮으면 바로 꺼진다"], "answer": 1, "explain": "큰 통 안에 산소가 더 많아서 촛불이 더 오래 타요."}], "summary": ["연소는 물질이 산소와 빠르게 반응해 빛과 열을 내는 현상이에요.", "연소에는 탈 물질, 산소, 발화점 이상의 온도가 모두 필요하고, 타면 물과 이산화 탄소가 생겨요.", "세 조건 중 하나 이상을 없애면 불이 꺼지고(소화), 불이 나면 119 신고 후 몸을 낮춰 대피해요."], "parent_tip": "부모님께: 아이들은 '불은 물로만 끈다'고 생각하기 쉽습니다. 식용유에 붙은 불에 물을 부으면 위험하다는 점을 꼭 알려 주세요. 집의 소화기 위치를 함께 확인하고, '우리 집에서 불이 나면 어디로 대피할까?'를 이야기하며 대피 경로를 정해 보시길 권합니다."}$json$::jsonb where slug = 's5-08';
update public.lessons set content = $json${"intro": "사탕 12개를 남김없이 똑같이 나누려면 몇 명에게 나눌 수 있을까요? 이 질문의 답을 찾다 보면 약수와 배수를 만나게 돼요.", "sections": [{"heading": "약수: 나누어떨어지게 하는 수", "paras": ["어떤 수를 나누어떨어지게 하는 수를 그 수의 약수라고 해요. 12는 1, 2, 3, 4, 6, 12로 나누면 나누어떨어지므로 이 수들이 12의 약수예요.", "1은 모든 수의 약수이고, 어떤 수 자신도 항상 그 수의 약수예요."], "example": "12의 약수: 1, 2, 3, 4, 6, 12", "figure": "사탕 12개를 1명, 2명, 3명, 4명, 6명, 12명에게 남김없이 나누는 모습을 표로 정리한 그림"}, {"heading": "배수: 몇 배 한 수", "paras": ["어떤 수를 1배, 2배, 3배…한 수를 그 수의 배수라고 해요. 4의 배수는 4, 8, 12, 16…처럼 끝없이 이어져요.", "4 × 3 = 12에서 12는 4와 3의 배수이고, 4와 3은 12의 약수예요. 약수와 배수는 곱셈식 하나로 연결되어 있어요."], "example": "4의 배수: 4, 8, 12, 16, …", "figure": "수직선 위에 4씩 뛰어 센 자리에 표시를 한 그림"}, {"heading": "공약수와 최대공약수", "paras": ["두 수의 공통된 약수를 공약수, 그중 가장 큰 수를 최대공약수라고 해요.", "18의 약수는 1, 2, 3, 6, 9, 18이고 24의 약수는 1, 2, 3, 4, 6, 8, 12, 24예요. 공약수는 1, 2, 3, 6이고 최대공약수는 6이에요. 공약수는 최대공약수의 약수와 같아요."], "example": "18과 24의 최대공약수 = 6", "figure": "18의 약수와 24의 약수를 두 원에 넣고 겹치는 부분에 공약수를 쓴 그림"}, {"heading": "이렇게 풀어요: 최소공배수 구하기", "paras": ["두 수의 공통된 배수를 공배수, 그중 가장 작은 수를 최소공배수라고 해요. ① 18과 24를 둘 다 나눌 수 있는 수로 나눠요: 2로 나누면 9와 12, 3으로 나누면 3과 4.", "② 더 이상 공통으로 나눌 수 없으면 멈춰요. ③ 나눈 수를 곱하면 최대공약수 2 × 3 = 6, 나눈 수와 남은 수를 모두 곱하면 최소공배수 2 × 3 × 3 × 4 = 72예요."], "example": "18과 24의 최소공배수 = 2 × 3 × 3 × 4 = 72", "figure": "18과 24를 공약수로 차례로 나누는 거꾸로 된 나눗셈 그림(ㄴ자 모양)"}], "keywords": [{"word": "약수", "meaning": "어떤 수를 나누어떨어지게 하는 수"}, {"word": "배수", "meaning": "어떤 수를 1배, 2배, 3배…한 수"}, {"word": "공약수", "meaning": "두 수의 공통된 약수"}, {"word": "최대공약수", "meaning": "공약수 중 가장 큰 수"}, {"word": "공배수", "meaning": "두 수의 공통된 배수"}, {"word": "최소공배수", "meaning": "공배수 중 가장 작은 수"}], "expressions": [], "quiz": [{"q": "20의 약수는 모두 몇 개일까요?", "choices": ["4개", "5개", "6개", "8개"], "answer": 2, "explain": "20의 약수는 1, 2, 4, 5, 10, 20으로 6개예요."}, {"q": "30과 45의 최대공약수는?", "choices": ["5", "10", "15", "90"], "answer": 2, "explain": "30과 45를 둘 다 나누어떨어지게 하는 가장 큰 수는 15예요."}, {"q": "6과 8의 최소공배수는?", "choices": ["2", "14", "24", "48"], "answer": 2, "explain": "6의 배수와 8의 배수에서 처음으로 같은 수는 24예요."}, {"q": "다음 중 7의 배수가 __아닌__ 것은?", "choices": ["14", "21", "36", "49"], "answer": 2, "explain": "36 ÷ 7 = 5 … 1로 나누어떨어지지 않아요."}, {"q": "A 버스는 12분마다, B 버스는 18분마다 출발해요. 두 버스가 동시에 출발한 뒤 다음에 동시에 출발하는 것은 몇 분 후일까요?", "choices": ["6분 후", "30분 후", "36분 후", "216분 후"], "answer": 2, "explain": "12와 18의 최소공배수인 36분 후예요."}], "summary": ["약수는 어떤 수를 나누어떨어지게 하는 수, 배수는 어떤 수를 몇 배 한 수예요.", "최대공약수는 공약수 중 가장 큰 수, 최소공배수는 공배수 중 가장 작은 수예요.", "공약수는 최대공약수의 약수이고, 공배수는 최소공배수의 배수예요."], "parent_tip": "약수와 배수의 뜻을 서로 바꿔 말하는 실수가 많습니다. \"12와 4 중 누가 누구의 약수야?\"처럼 짧게 자주 물어 주세요. 문장제에서 최대공약수와 최소공배수 중 무엇을 써야 할지 헷갈려 하면 \"똑같이 나누는 문제인지, 다시 만나는 문제인지\"를 먼저 생각하게 해 주세요."}$json$::jsonb where slug = 'm5-03';
update public.lessons set content = $json${"intro": "친구에게 가족사진을 보여 주며 \"우리 아빠야!\"라고 말해 본 적 있나요? 영어로도 똑같이 소개할 수 있어요.", "sections": [{"heading": "가족을 부르는 말", "paras": ["아빠는 father 또는 dad, 엄마는 mother 또는 mom이라고 해요.", "남자 형제는 brother, 여자 형제는 sister예요. 영어에서는 형·오빠·남동생을 모두 brother라고 불러요. 할아버지는 grandfather, 할머니는 grandmother예요."], "example": "dad(아빠), mom(엄마), brother(남자 형제), sister(여자 형제)", "figure": "할아버지, 할머니, 아빠, 엄마, 형, 여동생이 함께 있는 가족 그림에 영어 이름표"}, {"heading": "This is my ~ 로 소개해요", "paras": ["가족을 소개할 때는 \"This is my mom.(이분은 우리 엄마야.)\"처럼 This is my 뒤에 가족 이름을 붙여요.", "my는 '나의'라는 뜻이에요. 우리말로는 '우리 엄마'라고 하지만 영어에서는 my mom이라고 해요."], "example": "This is my brother. (이 아이는 우리 형이야.)", "figure": "아이가 가족사진을 가리키며 친구에게 소개하는 장면"}, {"heading": "누구인지 묻고 답하기", "paras": ["사진 속 사람이 누구인지 궁금하면 \"Who is he?(그는 누구야?)\" 또는 \"Who is she?(그녀는 누구야?)\"라고 물어요.", "남자는 he, 여자는 she를 써요. 대답은 \"He is my dad.\"처럼 해요."], "example": "Who is she? - She is my grandmother.", "figure": "사진 액자 속 할머니를 가리키는 두 친구 그림"}], "keywords": [{"word": "family", "meaning": "가족"}, {"word": "brother", "meaning": "남자 형제(형, 오빠, 남동생)"}, {"word": "sister", "meaning": "여자 형제(누나, 언니, 여동생)"}, {"word": "he / she", "meaning": "그 남자 / 그 여자"}, {"word": "my", "meaning": "나의, 우리"}], "expressions": [{"en": "This is my mom.", "ko": "이분은 우리 엄마야.", "note": "가족을 소개할 때"}, {"en": "This is my brother.", "ko": "이 아이는 우리 형(오빠, 남동생)이야."}, {"en": "Who is he?", "ko": "그는 누구야?", "note": "남자에 대해 물을 때"}, {"en": "Who is she?", "ko": "그녀는 누구야?", "note": "여자에 대해 물을 때"}, {"en": "He is my dad.", "ko": "그는 우리 아빠야."}, {"en": "She is my sister.", "ko": "그녀는 우리 언니(누나, 여동생)야."}, {"en": "I love my family.", "ko": "나는 우리 가족을 사랑해."}], "quiz": [{"q": "'할머니'를 영어로 하면?", "choices": ["grandfather", "mother", "grandmother", "sister"], "answer": 2, "explain": "할머니는 grandmother, 할아버지는 grandfather예요."}, {"q": "아빠를 친구에게 소개할 때 알맞은 말은?", "choices": ["This is my dad.", "Who is he?", "I'm dad.", "She is my dad."], "answer": 0, "explain": "This is my ~.로 소개해요. 아빠는 남자이니 She를 쓰면 안 돼요."}, {"q": "\"Who is she?\"에 알맞은 대답은?", "choices": ["He is my brother.", "She is my mom.", "It's a pencil.", "I'm fine."], "answer": 1, "explain": "she(그녀)를 물었으니 She is ~.로 대답해요."}, {"q": "brother가 가리킬 수 __없는__ 사람은?", "choices": ["형", "오빠", "남동생", "언니"], "answer": 3, "explain": "brother는 남자 형제예요. 언니는 sister예요."}, {"q": "\"I love my family.\"의 뜻은?", "choices": ["나는 우리 가족을 사랑해.", "나는 가족이 많아.", "이분은 우리 가족이야.", "우리 가족은 누구야?"], "answer": 0, "explain": "love는 '사랑하다', family는 '가족'이에요."}], "summary": ["가족은 dad, mom, brother, sister, grandfather, grandmother로 불러요.", "가족을 소개할 때는 This is my ~.라고 말해요.", "누구인지 물을 때 남자는 Who is he?, 여자는 Who is she?를 써요."], "parent_tip": "부모님께: 우리말과 달리 영어는 나이와 상관없이 brother, sister를 쓰기 때문에 아이가 \"형은 영어로 뭐야?\"라고 헷갈려할 수 있습니다. 가족사진을 함께 보며 \"Who is he?\"라고 묻고 아이가 He/She를 골라 대답하게 해 주세요."}$json$::jsonb where slug = 'e3-03';
update public.lessons set content = $json${"intro": "곧 다가올 방학이나 주말에 하고 싶은 일이 있나요? 앞으로 할 일을 영어로 말하는 방법을 배워 봐요.", "sections": [{"heading": "앞으로 할 일: be going to", "paras": ["앞으로 할 계획을 말할 때는 \"I'm going to visit my uncle.(나는 삼촌 댁에 갈 거야.)\"처럼 be going to를 써요.", "be going to 뒤에는 동사의 원래 모양을 써요. I와는 am, he·she와는 is, you·we·they와는 are를 짝지어요."], "example": "I'm going to swim. / She is going to read books.", "figure": "수영복과 튜브를 챙기며 방학 계획을 세우는 아이"}, {"heading": "때를 나타내는 말", "paras": ["앞으로의 때를 말할 때는 tomorrow(내일), this weekend(이번 주말), next week(다음 주), this summer(이번 여름) 같은 말을 함께 써요.", "\"I'm going to go camping this weekend.(이번 주말에 캠핑을 갈 거야.)\"처럼 문장 끝에 붙이면 돼요."], "example": "this weekend, next week, tomorrow", "figure": "달력에 이번 주말, 다음 주가 색칠된 그림"}, {"heading": "계획 묻고 답하기", "paras": ["\"What are you going to do this weekend?(이번 주말에 무엇을 할 거니?)\"라고 물어요.", "\"Are you going to ~?\"로 물으면 \"Yes, I am.\" 또는 \"No, I'm not.\"으로 대답해요. 함께하자고 할 때는 \"Let's go together!(같이 가자!)\"라고 해요."], "example": "Are you going to play baseball? - Yes, I am.", "figure": "두 친구가 달력을 보며 주말 계획을 이야기하는 장면"}], "keywords": [{"word": "plan", "meaning": "계획"}, {"word": "be going to", "meaning": "~할 것이다, ~할 예정이다"}, {"word": "tomorrow", "meaning": "내일"}, {"word": "this weekend", "meaning": "이번 주말"}, {"word": "next week", "meaning": "다음 주"}], "expressions": [{"en": "What are you going to do this weekend?", "ko": "이번 주말에 무엇을 할 거니?", "note": "계획을 물을 때"}, {"en": "I'm going to visit my uncle.", "ko": "나는 삼촌 댁에 갈 거야."}, {"en": "I'm going to go camping.", "ko": "나는 캠핑을 갈 거야."}, {"en": "Are you going to swim?", "ko": "너 수영할 거니?"}, {"en": "Yes, I am.", "ko": "응, 그럴 거야."}, {"en": "No, I'm not.", "ko": "아니, 안 할 거야."}, {"en": "Let's go together!", "ko": "같이 가자!", "note": "함께하자고 할 때"}, {"en": "Have a nice weekend!", "ko": "주말 잘 보내!", "note": "헤어질 때"}], "quiz": [{"q": "앞으로의 계획을 물을 때 알맞은 말은?", "choices": ["What did you do?", "What are you going to do?", "What do you like?", "What time is it?"], "answer": 1, "explain": "be going to는 앞으로 할 일을 나타내요."}, {"q": "'나는 내일 책을 읽을 거야.'를 영어로 하면?", "choices": ["I read books yesterday.", "I'm reading books.", "I'm going to read books tomorrow.", "I read books tomorrow yesterday."], "answer": 2, "explain": "앞으로 할 일은 I'm going to + 동사 원래 모양으로 말해요."}, {"q": "빈칸에 알맞은 말은? She ___ going to visit Jeju.", "choices": ["is", "am", "are", "do"], "answer": 0, "explain": "she와 짝이 되는 be동사는 is예요."}, {"q": "\"Are you going to play soccer?\"에 '아니'라고 대답할 때는?", "choices": ["No, I don't.", "Yes, I am.", "No, you aren't.", "No, I'm not."], "answer": 3, "explain": "Are you ~?로 물었으니 No, I'm not.으로 대답해요."}, {"q": "미래의 때를 나타내는 말이 __아닌__ 것은?", "choices": ["yesterday", "tomorrow", "next week", "this weekend"], "answer": 0, "explain": "yesterday(어제)는 지나간 때예요."}], "summary": ["앞으로의 계획은 be going to + 동사 원래 모양으로 말해요.", "tomorrow, this weekend, next week 같은 때를 나타내는 말을 함께 써요.", "What are you going to do?로 묻고, Are you going to ~?에는 Yes, I am./No, I'm not.으로 대답해요."], "parent_tip": "부모님께: 아이들은 지난 일(yesterday)과 앞으로의 일(tomorrow)에 쓰는 동사 모양을 섞어 쓰기 쉽습니다. 금요일 저녁에 \"What are you going to do this weekend?\"라고 묻고, 월요일에는 \"What did you do last weekend?\"라고 물어 과거와 미래를 비교해 보게 해 주세요."}$json$::jsonb where slug = 'e5-07';
